// Generar fecha de hoy en formato ddmmaaaa (requerido por API Mercado Público)
const hoy = new Date();
const dd = String(hoy.getDate()).padStart(2, '0');
const mm = String(hoy.getMonth() + 1).padStart(2, '0');
const yyyy = hoy.getFullYear();

return [{
  json: {
    fecha_api: `${dd}${mm}${yyyy}`,
    fecha_iso: hoy.toISOString().split('T')[0],
    timestamp: hoy.toISOString()
  }
}];

// ═══════════════════════════════════════════════════════════════
// JORGE DÍAZ · RADAR RECASUR v2.0
// Scoring multirrubro · Boost Magallanes · Alerta Dimarsa
// Calibrado con data real 22-abr-2026
// ═══════════════════════════════════════════════════════════════

// ─── CONFIGURACIÓN POR RUBRO ───
const RUBROS = {
  nautico_buceo: {
    keywords: ['buceo', 'buzo', 'rebreather', 'regulador', 'traje seco', 'traje humedo',
               'compresor aire', 'compresor buceo', 'cilindro buceo', 'banco de aire',
               'umbilical', 'subacuatico', 'subacuática', 'rov', 'embarcacion', 'bote',
               'lancha', 'motor fuera de borda', 'motor centrado', 'motor yamaha',
               'hdpe', 'winche', 'salvamento', 'cabo polipropileno'],
    peso: 15,
    nivel: 'fuerte', // ← Recasur gana frecuentemente
    bonus: 0
  },
  seguridad: {
    keywords: ['chaleco salvavidas', 'balsa salvavidas', 'ropa termica', 'ropa térmica',
               'ropa de seguridad', 'equipo de salvataje', 'salvataje maritimo',
               'pirotecnia', 'señalizacion maritima', 'traje ignifugo'],
    peso: 13,
    nivel: 'fuerte',
    bonus: 0
  },
  maquinarias: {
    keywords: ['maquinaria agricola', 'maquinaria náutica', 'maquinaria pesada',
               'grua horquilla', 'grúa horquilla', 'motobomba', 'hidrolavadora',
               'generador electrico', 'motor estacionario'],
    peso: 13,
    nivel: 'fuerte',
    bonus: 0
  },
  automotriz: {
    keywords: ['neumatico', 'neumático', 'repuesto automotor', 'repuesto automotriz',
               'repuesto motor', 'filtro motor', 'vehiculo', 'vehículo', 'camioneta',
               'lubricante'],
    peso: 12,
    nivel: 'mixto', // ← lubricantes es débil (Mobil), resto okay
    bonus: 0
  },
  comunicaciones: {
    keywords: ['vhf', 'uhf', 'hf maritimo', 'hf marítimo', 'radio maritima',
               'radio marítima', 'gps marino', 'gps maritimo', 'gps marítimo',
               'radar marino', 'sonar', 'navegacion maritima', 'ais'],
    peso: 11,
    nivel: 'debil', // ← perdieron aquí el último año
    bonus: 5 // boost extra para empujar más ofertas en este rubro
  },
  electromecanica: {
    keywords: ['panel solar', 'fotovoltaico', 'sistema hidraulico', 'sistema hidráulico',
               'bomba hidraulica', 'bomba centrifuga'],
    peso: 12,
    nivel: 'mixto',
    bonus: 0
  },
  ferreteria: {
    keywords: ['ferreteria', 'ferretería', 'herramientas', 'elementos de ferreteria',
               'accesorios ferreteros'],
    peso: 8,
    nivel: 'secundario',
    bonus: 0
  }
};

const KEYWORDS_WARM = ['ropa', 'vestuario', 'accesorios para vehiculos',
                       'articulos de seguridad', 'equipos', 'suministro'];

// Excluir licitaciones que NO son de compra de productos
const KEYWORDS_EXCLUDE = ['arriendo', 'alquiler', 'consultoria', 'consultoría',
                         'asesoria técnica', 'asesoría técnica', 'capacitacion',
                         'capacitación', 'mantencion integral', 'mantención integral',
                         'servicio de reparacion'];

// ─── CLIENTES CLAVE DE RECASUR ───
const CLIENTES_RECASUR = {
  'INDESPA': 25,           // muy alta · sinergia pesca/náutico Magallanes
  'MUNICIPAL': 25,         // muy alta
  'GOBIERNO REGIONAL': 25, // muy alta · GORE
  'HOSPITAL': 25,          // muy alta
  'ISP': 15,               // alta · Instituto Salud Pública
  'CARABINEROS': 15,       // alta
  'POLICIA DE INVESTIGA': 15, // PDI
  'FUERZAS ARMADAS': 15,   // FFAA
  'ARMADA': 15,
  'EJERCITO': 15,
  'FUERZA AEREA': 15,
  'MINISTERIO DE AGRICULTURA': 15, // MINAGRI
  'SAG': 15,               // Servicio Agrícola Ganadero (MINAGRI)
  'MOP': 10,               // media
  'INDAP': 10,             // media
  'GOBERNACION MARITIMA': 10, // media
  'DIRECTEMAR': 10,
  'MINISTERIO DE EDUCACION': 10,
  'VIALIDAD': 10
};

// ─── REGIONES PRIORITARIAS (Recasur base Magallanes) ───
const REGIONES_BOOST = {
  'MAGALLANES': 30,        // sede principal · ventaja logística total
  'ANTARTICA': 30,
  'AYSEN': 15,             // zona sur cercana
  'AYSÉN': 15
};

// ─── COMPETIDORES A DETECTAR ───
const COMPETIDORES = {
  'DIMARSA': { nivel: 'archienemigo', alerta: true },
  'DIMARINE': { nivel: 'archienemigo', alerta: true }, // división náutica Dimarsa
  'SALFA': { nivel: 'alto', alerta: false },
  'MOBIL': { nivel: 'alto', alerta: false },
  'STARLINE': { nivel: 'alto', alerta: false },
  'KAUFFMAN': { nivel: 'alto', alerta: false },
  'HEVIA': { nivel: 'medio', alerta: false },
  'KRILL': { nivel: 'medio', alerta: false },
  'ITURRI': { nivel: 'bajo', alerta: false }
};

// ═══════════════════════════════════════════════════════════════
// PROCESAR CADA LICITACIÓN
// ═══════════════════════════════════════════════════════════════

const item = $json;

// Normalizar campos
const codigo = item.CodigoExterno || '';
const nombre = (item.Nombre || '').toLowerCase();
const descripcion = (item.Descripcion || '').toLowerCase();
const organismo = (item.NombreOrganismo || '').toUpperCase();
const region = (item.Region || '').toUpperCase();
const monto = parseFloat(item.MontoEstimado || 0);
const fechaCierre = item.FechaCierre || null;
const textoCompleto = `${nombre} ${descripcion} ${organismo.toLowerCase()} ${region.toLowerCase()}`;

// ─── FILTRO DE EXCLUSIÓN TEMPRANA ───
const tieneExclude = KEYWORDS_EXCLUDE.some(k => textoCompleto.includes(k));
if (tieneExclude) return []; // descartar, no es compra de productos

// ─── DETECTAR RUBRO PRINCIPAL ───
let rubroPrincipal = null;
let rubroScore = 0;
let hotMatches = [];

for (const [rubro, config] of Object.entries(RUBROS)) {
  const matches = config.keywords.filter(k => textoCompleto.includes(k));
  if (matches.length > 0) {
    const score = matches.length * config.peso + config.bonus;
    if (score > rubroScore) {
      rubroScore = score;
      rubroPrincipal = rubro;
    }
    hotMatches = hotMatches.concat(matches);
  }
}

// Si no matcheó ningún rubro hot, revisar warm
let warmMatches = [];
if (!rubroPrincipal) {
  warmMatches = KEYWORDS_WARM.filter(k => textoCompleto.includes(k));
  if (warmMatches.length === 0) return []; // descartar, no es del rubro
  rubroPrincipal = 'warm_general';
}

// ─── CALCULAR SCORE GLOBAL ───
let score = 0;
let matchesInfo = [];

// 1. Keywords del rubro (máx 45)
const keywordScore = Math.min(rubroScore, 45);
score += keywordScore;
if (hotMatches.length > 0) {
  matchesInfo.push(`${hotMatches.length} keyword(s) ${rubroPrincipal}`);
}
if (warmMatches.length > 0) {
  const warmScore = Math.min(warmMatches.length * 8, 20);
  score += warmScore;
  matchesInfo.push(`${warmMatches.length} keyword(s) generales`);
}

// 2. Cliente clave de Recasur
let clienteBoost = 0;
let clienteDetectado = null;
for (const [cliente, boost] of Object.entries(CLIENTES_RECASUR)) {
  if (organismo.includes(cliente)) {
    if (boost > clienteBoost) {
      clienteBoost = boost;
      clienteDetectado = cliente;
    }
  }
}
score += clienteBoost;
if (clienteDetectado) matchesInfo.push(`cliente: ${clienteDetectado}`);

// 3. Boost geográfico (Magallanes = +30) ← LA GRAN VENTAJA
let regionBoost = 0;
let regionDetectada = null;
for (const [reg, boost] of Object.entries(REGIONES_BOOST)) {
  if (region.includes(reg) || organismo.includes(reg)) {
    if (boost > regionBoost) {
      regionBoost = boost;
      regionDetectada = reg;
    }
  }
}
score += regionBoost;
if (regionDetectada) matchesInfo.push(`región: ${regionDetectada}`);

// 4. Urgencia de cierre
let diasAlCierre = null;
if (fechaCierre) {
  const cierre = new Date(fechaCierre);
  const ahora = new Date();
  diasAlCierre = Math.ceil((cierre - ahora) / (1000 * 60 * 60 * 24));
  if (diasAlCierre > 0 && diasAlCierre <= 3) {
    score += 10;
    matchesInfo.push('⚠️ cierra en ≤3 días');
  } else if (diasAlCierre > 0 && diasAlCierre <= 7) {
    score += 5;
    matchesInfo.push('cierra pronto');
  }
  // Descartar si cierra en menos de 20 días (regla de Jorge)
  if (diasAlCierre > 0 && diasAlCierre < 20) {
    // Aún se muestra pero con flag
    matchesInfo.push('⚠️ poco tiempo preparación');
  }
}

// 5. Monto sweet spot ($20M–$200M)
if (monto >= 20000000 && monto <= 200000000) {
  score += 10;
  matchesInfo.push('monto sweet spot');
} else if (monto > 200000000) {
  score += 15; // licitación grande = prioridad máxima
  matchesInfo.push('💰 monto alto');
} else if (monto >= 500000) {
  score += 3;
}

// Cap del score
score = Math.min(score, 100);

// ─── DETECTAR COMPETIDORES (solo si la API devuelve oferentes) ───
let competidoresDetectados = [];
let alertaDimarsa = false;
const oferentes = item.Items?.Listado || [];
for (const [comp, config] of Object.entries(COMPETIDORES)) {
  if (JSON.stringify(oferentes).toUpperCase().includes(comp)) {
    competidoresDetectados.push({ nombre: comp, nivel: config.nivel });
    if (config.alerta) alertaDimarsa = true;
  }
}

// ─── CLASIFICACIÓN HOT/WARM/COLD ───
let categoria;
if (score >= 75 || alertaDimarsa) {
  categoria = 'hot';
} else if (score >= 45) {
  categoria = 'warm';
} else if (score >= 25) {
  categoria = 'cold';
} else {
  return []; // descartar, score muy bajo
}

// ─── SUGERENCIA TÁCTICA ───
let sugerenciaTactica = '';
if (alertaDimarsa) {
  sugerenciaTactica = '🚨 DIMARSA participa. NO competir por precio. Destacar: entrega rápida, stock local Magallanes, post-venta con técnico en Punta Arenas.';
} else if (regionDetectada === 'MAGALLANES' || regionDetectada === 'ANTARTICA') {
  sugerenciaTactica = '✨ Ventaja logística Magallanes. Destacar entrega rápida y stock inmediato.';
} else if (RUBROS[rubroPrincipal]?.nivel === 'debil') {
  sugerenciaTactica = '⚡ Rubro débil históricamente. Revisar precio con margen ajustado y destacar post-venta.';
} else if (RUBROS[rubroPrincipal]?.nivel === 'fuerte') {
  sugerenciaTactica = '💪 Rubro fuerte de Recasur. Confianza total, postular con ticket estándar.';
}

// ═══════════════════════════════════════════════════════════════
// OUTPUT
// ═══════════════════════════════════════════════════════════════

return [{
  json: {
    codigo_externo: item.CodigoExterno,
    nombre: item.Nombre,
    descripcion: (item.Descripcion || '').substring(0, 500),
    organismo: item.NombreOrganismo,
    codigo_organismo: item.CodigoOrganismo,
    region: item.Region || null,
    monto_estimado: monto,
    moneda: item.Moneda || 'CLP',
    fecha_publicacion: item.FechaPublicacion,
    fecha_cierre: item.FechaCierre,
    estado: item.CodigoEstado,
    tipo: item.Tipo,
    dias_al_cierre: diasAlCierre,
    score: score,
    categoria: categoria,
    rubro_principal: rubroPrincipal,
    nivel_rubro: RUBROS[rubroPrincipal]?.nivel || 'secundario',
    matches: matchesInfo.join(' · '),
    cliente_detectado: clienteDetectado,
    region_detectada: regionDetectada,
    competidores_detectados: competidoresDetectados.map(c => c.nombre).join(', '),
    alerta_dimarsa: alertaDimarsa,
    sugerencia_tactica: sugerenciaTactica,
    url_ficha: `https://www.mercadopublico.cl/Procurement/Modules/RFB/DetailsAcquisition.aspx?idlicitacion=${item.CodigoExterno}`,
    capturado_en: new Date().toISOString()
  }
}];
